from itertools import combinations

class Solution:
    def mostVisitedPattern(self, username: List[str], timestamp: List[int], website: List[str]) -> List[str]:
        visits = defaultdict(list)
        for u, t, w in zip(username, timestamp, website):
            visits[u].append((t, w))
        for u in visits:
            visits[u].sort(key=lambda x: x[0])

        # dictionary from pattern tuple to set of users
        pattern_users = defaultdict(set)

        for u in visits:
            websites = [w for _, w in visits[u]]
            # generate all unique combinations of 3 websites in order
            combos = set(combinations(websites, 3))
            for pattern in combos:
                pattern_users[pattern].add(u)

        # find the max user count
        max_count = 0
        max_patterns = []
        for pattern, users in pattern_users.items():
            count = len(users)
            if count > max_count:
                max_count = count
                max_patterns = [pattern]
            elif count == max_count:
                max_patterns.append(pattern)

        return min(max_patterns)  # lex smallest pattern"}
